def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Find all rows and columns that are uniform (all same value)
    uniform_rows = set()
    uniform_cols = set()

    for r in range(rows):
        if len(set(grid[r])) == 1:
            uniform_rows.add(r)

    for c in range(cols):
        if len(set(grid[r][c] for r in range(rows))) == 1:
            uniform_cols.add(c)

    # Apply transformation: change to 2
    result = []
    for r in range(rows):
        row = []
        for c in range(cols):
            if r in uniform_rows or c in uniform_cols:
                row.append(2)
            else:
                row.append(grid[r][c])
        result.append(row)

    return result

